package io.github.diodeme.ji.session.memory;

import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.session.tree.SessionDocument;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.UnaryOperator;

/** In-memory reference implementation of the canonical Session repository contract. */
public final class MemorySessionRepository implements SessionRepository {
    private final Map<String, SessionDocument> documents = new LinkedHashMap<>();

    @Override
    public synchronized SessionDocument create(String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        if (documents.containsKey(sessionId)) throw new IllegalStateException("session already exists: " + sessionId);
        SessionDocument document = SessionDocument.empty(sessionId, model, workingDirectory, createdAt);
        documents.put(sessionId, document);
        return document;
    }

    @Override
    public synchronized Optional<SessionDocument> load(String sessionId) {
        return Optional.ofNullable(documents.get(sessionId));
    }

    @Override
    public synchronized List<SessionDocument.Metadata> list() {
        return documents.values().stream().map(SessionDocument::metadata)
                .sorted(java.util.Comparator.comparing(SessionDocument.Metadata::createdAt).reversed()).toList();
    }

    @Override
    public synchronized SessionDocument update(String sessionId, long expectedRevision,
                                               UnaryOperator<SessionDocument> transition) {
        SessionDocument current = require(sessionId, expectedRevision);
        SessionDocument next = transition.apply(current);
        requireSuccessor(current, next);
        documents.put(sessionId, next);
        return next;
    }

    @Override
    public synchronized SessionDocument fork(String sourceSessionId, String newSessionId, String lane,
                                             Optional<String> targetEntryId, SessionDocument.ForkPosition position,
                                             Instant createdAt, long expectedSourceRevision) {
        if (documents.containsKey(newSessionId)) throw new IllegalStateException("session already exists: " + newSessionId);
        SessionDocument source = require(sourceSessionId, expectedSourceRevision);
        SessionDocument fork = source.fork(newSessionId, lane, targetEntryId, position, createdAt);
        documents.put(newSessionId, fork);
        return fork;
    }

    @Override
    public synchronized void delete(String sessionId, long expectedRevision) {
        SessionDocument current = documents.get(sessionId);
        if (current == null) return;
        requireRevision(current, expectedRevision);
        documents.remove(sessionId);
    }

    private SessionDocument require(String sessionId, long expectedRevision) {
        SessionDocument current = documents.get(sessionId);
        if (current == null) throw new IllegalStateException("session not found: " + sessionId);
        requireRevision(current, expectedRevision);
        return current;
    }

    private static void requireRevision(SessionDocument current, long expectedRevision) {
        if (current.revision() != expectedRevision) {
            throw new IllegalStateException("session revision conflict: expected " + expectedRevision
                    + ", current " + current.revision());
        }
    }

    private static void requireSuccessor(SessionDocument current, SessionDocument next) {
        if (next == null || !next.metadata().sessionId().equals(current.metadata().sessionId())
                || next.revision() != Math.incrementExact(current.revision())) {
            throw new IllegalStateException("Session transition must preserve identity and advance revision once");
        }
    }
}
